79: // Purpose: Creates the directory, returning true if it is created, or if it already existed
80: //-----------------------------------------------------------------------------
81: bool BCreateDirectory( const char *pchPath )
82: {
83: #ifdef WIN32
84: 	std::wstring wPath = UTF8to16( pchPath );
85: 	if ( ::CreateDirectoryW( wPath.c_str(), NULL ) )
86: 		return true;
87: 
88: 	if ( ::GetLastError() == ERROR_ALREADY_EXISTS )
89: 		return true;
90: 
91: 	return false;
92: #else
93: 	int i = mkdir( pchPath, S_IRWXU | S_IRWXG | S_IRWXO );
94: 	if ( i == 0 )
95: 		return true;
96: 	if ( errno == EEXIST )
97: 		return true;
98: 
99: 	return false;
100: #endif
101: }
