135: //-----------------------------------------------------------------------------
136: // Purpose: Initialize iteration structure
137: //-----------------------------------------------------------------------------
138: void CDirIterator::Init( const std::string &sPathAndPattern )
139: {
140: #if defined( _WIN32 )
141: 	m_pFindData = new WIN32_FIND_DATAW;
142: 	memset( m_pFindData, 0, sizeof( *m_pFindData ) );
143: 
144: 	std::wstring sWPathAndPattern = UTF8to16( sPathAndPattern.c_str() );
145: 
146: 	m_hFind = FindFirstFileW( sWPathAndPattern.c_str(), m_pFindData );
147: 	bool bSuccess = ( m_hFind != HMD_INVALID_HANDLE_VALUE );
148: 	// Conversion should never fail with valid filenames...
149: 	if ( bSuccess )
150: 	{
151: 		m_sFilename = UTF16to8( m_pFindData->cFileName );
152: 	}
153: #else
154: 	m_pFindData = new _finddata_t;
155: 	memset( m_pFindData, 0, sizeof( *m_pFindData ) );
156: 
157: 	m_hFind = _findfirst( sPathAndPattern.c_str(), m_pFindData );
158: 	bool bSuccess = ( m_hFind != -1 );
159: #endif
160: 
161: 	if ( !bSuccess )
162: 	{
163: 		m_bNoFiles = true;
164: 		m_bUsedFirstFile = true;
165: 	}
166: 	else
167: 	{
168: 		m_bNoFiles = false;
169: 		// if we're pointing at . or .., set it as used
170: 		// so we'll look for the next item when BNextFile() is called
171: 		m_bUsedFirstFile = !BValidFilename();
172: 	}
173: }
