315: // Purpose: utility for converting a regular time to a system filetime
316: //-----------------------------------------------------------------------------
317: FILETIME UnixTimeToFileTime( int64_t t )
318: {
319: 	FILETIME retf;
320: 	long long int ll;
321: 	ll = ( ( long long )t * 10000000LL );
322: 	ll += 116444736000000000LL;
323: 	retf.dwHighDateTime = ll >> 32;
324: 	retf.dwLowDateTime = ll & 0x00000000FFFFFFFF;
325: 	return retf;
326: }
