330: // Purpose: utility for converting a system filetime to a regular time
331: //-----------------------------------------------------------------------------
332: int64_t FileTimeToUnixTime( FILETIME filetime )
333: {
334: 	long long int t = filetime.dwHighDateTime;
335: 	t <<= 32;
336: 	t += ( unsigned long )filetime.dwLowDateTime;
337: 	t -= 116444736000000000LL;
338: 	return t / 10000000;
339: }
